import{_ as t,o as a,c as i,a2 as n}from"./chunks/framework.mRCPFc5l.js";const g=JSON.parse('{"title":"Creating and editing entries","description":"Capture, change, and share entries in a Grid.","frontmatter":{"title":"Creating and editing entries","description":"Capture, change, and share entries in a Grid."},"headers":[],"relativePath":"en/grids/eintraege.md","filePath":"en/grids/eintraege.md","lastUpdated":1787319236000}'),r={name:"en/grids/eintraege.md"};function o(s,e,d,l,h,c){return a(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="creating-and-editing-entries" tabindex="-1">Creating and editing entries <a class="header-anchor" href="#creating-and-editing-entries" aria-label="Permalink to &quot;Creating and editing entries&quot;">​</a></h1><p>An <strong>entry</strong> is a row in a Grid.</p><h2 id="creating" tabindex="-1">Creating <a class="header-anchor" href="#creating" aria-label="Permalink to &quot;Creating&quot;">​</a></h2><p>There are four ways to create a new entry:</p><table tabindex="0"><thead><tr><th>Way</th><th>When it makes sense</th></tr></thead><tbody><tr><td>Directly in the table</td><td>While building, for quick additions</td></tr><tr><td>Via <strong>Create new entry</strong></td><td>When many fields need filling in</td></tr><tr><td>Via a <a href="/en/formulare/formular-erstellen">Form</a></td><td>When other people are supplying the data</td></tr><tr><td>Via a <a href="/en/flows/aktionen">Flow</a></td><td>When entries should be created automatically</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">New entries trigger flows</p><p>If a flow with the <em>New entry</em> trigger is attached to this Grid, it starts on <strong>every</strong> new entry — no matter which way it was created.</p><p>That also applies to <a href="/en/grids/csv-import">CSV import</a>: 500 imported rows mean 500 flow runs.</p></div><h2 id="editing" tabindex="-1">Editing <a class="header-anchor" href="#editing" aria-label="Permalink to &quot;Editing&quot;">​</a></h2><h3 id="in-the-table" tabindex="-1">In the table <a class="header-anchor" href="#in-the-table" aria-label="Permalink to &quot;In the table&quot;">​</a></h3><p>Clicking a cell makes it editable. Changes are saved immediately — there&#39;s no save button.</p><div class="tip custom-block"><p class="custom-block-title">No undo in the table</p><p>An overwritten cell can&#39;t be restored with a keyboard shortcut. The <a href="/en/grids/versionsverlauf">version history</a>, however, shows the previous value and lets you restore it.</p></div><h3 id="in-the-detail-view" tabindex="-1">In the detail view <a class="header-anchor" href="#in-the-detail-view" aria-label="Permalink to &quot;In the detail view&quot;">​</a></h3><p>Clicking the row opens the entry with all fields listed one below the other — including ones hidden in the current view.</p><p>The dialog is called <strong>Edit entry</strong>.</p><div class="tip custom-block"><p class="custom-block-title">Hidden fields aren&#39;t gone</p><p>A common misunderstanding: what&#39;s hidden in a view still exists and remains visible and editable in the detail view. → <a href="/en/ansichten/spalten-verwalten">Manage columns</a></p></div><h2 id="emoticon-shortcuts" tabindex="-1">Emoticon shortcuts <a class="header-anchor" href="#emoticon-shortcuts" aria-label="Permalink to &quot;Emoticon shortcuts&quot;">​</a></h2><p>In text fields, some character sequences are automatically replaced by a symbol as you type:</p><table tabindex="0"><thead><tr><th>Input</th><th>Becomes</th></tr></thead><tbody><tr><td><code>(/)</code></td><td>✅</td></tr><tr><td><code>(x)</code> or <code>(×)</code></td><td>❌</td></tr><tr><td><code>(!)</code></td><td>❗</td></tr><tr><td><code>(?)</code></td><td>❓</td></tr><tr><td><code>(Y)</code> or <code>(y)</code></td><td>👍</td></tr><tr><td><code>(N)</code> or <code>(n)</code></td><td>👎</td></tr></tbody></table><p>The replacement only kicks in if the shortcut is <strong>at the start or after a space</strong> and is followed by a space, a line break, or the end of the field. So text like <code>Version(x)</code> stays unchanged.</p><div class="tip custom-block"><p class="custom-block-title">Useful for status columns</p><p>For short notes — done, open, needs follow-up — the symbols are easy to spot at a glance and don&#39;t need their own select column.</p><p>For anything you want to evaluate, a <strong>Single Select</strong> or <strong>Checkmark</strong> field is still better: you can then filter and group by it, which doesn&#39;t work meaningfully with a symbol in free text.</p></div><h2 id="locked-and-read-only-fields" tabindex="-1">Locked and read-only fields <a class="header-anchor" href="#locked-and-read-only-fields" aria-label="Permalink to &quot;Locked and read-only fields&quot;">​</a></h2><p>Some fields can&#39;t be edited:</p><table tabindex="0"><thead><tr><th>Reason</th><th>Recognizable by</th></tr></thead><tbody><tr><td><strong>Calculated type</strong> — Use linked value, Calculate sum, Formula</td><td>Always read-only</td></tr><tr><td><strong>Automatic field</strong> — Created at, Created by</td><td>Always read-only</td></tr><tr><td><strong>Locked in this view</strong></td><td>Notice <em>Column is locked in this view</em></td></tr><tr><td><strong>Missing permission</strong></td><td>No edit mode, no message</td></tr></tbody></table><h2 id="when-an-entry-disappears" tabindex="-1">When an entry disappears <a class="header-anchor" href="#when-an-entry-disappears" aria-label="Permalink to &quot;When an entry disappears&quot;">​</a></h2><p>If you edit an entry so it no longer matches the view&#39;s filter, ApptiveGrid reports <strong>Row filtered</strong> and hides it.</p><div class="tip custom-block"><p class="custom-block-title">The entry isn&#39;t gone</p><p>It just no longer meets the filter condition. It still exists in an unfiltered view. This typically happens when you set the status to <code>Done</code> in an &quot;Open tasks&quot; view.</p></div><h2 id="working-at-the-same-time" tabindex="-1">Working at the same time <a class="header-anchor" href="#working-at-the-same-time" aria-label="Permalink to &quot;Working at the same time&quot;">​</a></h2><p>If someone else changes the Grid, ApptiveGrid reports <strong>This Grid has been updated</strong>. Reload the view to see the current state.</p><h2 id="sharing-an-entry" tabindex="-1">Sharing an entry <a class="header-anchor" href="#sharing-an-entry" aria-label="Permalink to &quot;Sharing an entry&quot;">​</a></h2><p>Use the row menu&#39;s <strong>Share entry</strong> to create a link that lets one person edit <strong>exactly this</strong> entry.</p><blockquote><p><strong>Share a form to edit</strong><em>Share a form to edit the entry with others.</em></p></blockquote><p>This requires a form on this Grid. If there isn&#39;t one: <em>Create a form first to share the entry with others.</em></p><div class="tip custom-block"><p class="custom-block-title">Collect feedback without giving access</p><p>This lets external people add to or correct a single record without <a href="/en/zusammenarbeit/personen-einladen">inviting them to the Space</a> — and without them seeing other entries.</p></div><p>→ <a href="/en/formulare/eintraege-bearbeiten">Editing entries via a form</a></p><h2 id="printing-an-entry" tabindex="-1">Printing an entry <a class="header-anchor" href="#printing-an-entry" aria-label="Permalink to &quot;Printing an entry&quot;">​</a></h2><p>From the detail view, you can open an entry in a print view.</p><h2 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">The number of entries per Grid depends on your plan</p><p>As you approach the limit, ApptiveGrid shows a notice.</p></div><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/en/grids/suche">Search</a> — find entries again</li><li><a href="/en/grids/eintraege-loeschen">Deleting entries</a></li><li><a href="/en/grids/versionsverlauf">Version history</a></li><li><a href="/en/grids/felder">Creating and changing fields</a></li></ul>',39)])])}const u=t(r,[["render",o]]);export{g as __pageData,u as default};
